-- ETAPA 59B billing base
create table if not exists public.billing_plans (id uuid primary key, code text not null unique, name text not null, description text, price_cents integer not null, currency text not null default 'BRL', billing_cycle text not null default 'monthly', trial_days integer not null default 15, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.account_subscriptions (id uuid primary key, account_id uuid not null, plan_id uuid not null, status text not null default 'trialing', trial_start_at timestamptz, trial_end_at timestamptz, current_period_start timestamptz, current_period_end timestamptz, asaas_customer_id text, asaas_subscription_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.billing_customers (id uuid primary key, account_id uuid not null, asaas_customer_id text, name text not null, email text, phone text, cpf_cnpj text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.billing_payments (id uuid primary key, account_id uuid not null, subscription_id uuid, asaas_payment_id text, asaas_subscription_id text, status text not null, value_cents integer, due_date date, paid_at timestamptz, invoice_url text, bank_slip_url text, raw_payload jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.billing_webhook_events (id uuid primary key, provider text not null default 'asaas', provider_event_id text, event_type text not null, payment_id text, subscription_id text, payload jsonb not null, processed_at timestamptz, processing_status text not null default 'received', created_at timestamptz not null default now());
create index if not exists idx_billing_customers_account_id on public.billing_customers(account_id);
